(window.TNQ=window.TNQ||[]).push({"terms":{"항고소송":{"d":"행정청의 처분이나 부작위에 불복해 그 위법을 다투는 소송으로 취소·무효등확인·부작위위법확인소송이 있다.","r":["취소소송","당사자소송"]},"취소소송":{"d":"위법한 처분등을 취소하거나 변경해 달라고 구하는 항고소송이다.","r":["항고소송"]},"무효등 확인소송":{"d":"처분등의 효력 유무나 존재 여부를 확인해 달라고 구하는 항고소송이다.","r":["항고소송"]},"부작위위법확인소송":{"d":"행정청이 법률상 의무가 있는데도 처분을 하지 않는 것이 위법함을 확인해 달라고 구하는 항고소송이다.","r":["항고소송"]},"기관소송":{"d":"국가나 공공단체의 기관 상호 간 권한의 존부나 행사에 관한 다툼을 해결하는 소송이다.","r":["민중소송"]},"민중소송":{"d":"자기의 법률상 이익과 관계없이 기관의 법 위반 행위의 시정을 구하는 객관소송이다.","r":["기관소송"]},"객관소송":{"d":"개인의 권리 구제가 아니라 법질서의 적정한 유지를 목적으로 법률이 정한 경우에만 허용되는 소송이다.","r":["민중소송","기관소송"]},"적극적 변경":{"d":"법원이 처분을 취소하는 데 그치지 않고 다른 내용으로 바꾸라고 하는 것으로 취소소송에서는 허용되지 않는다.","r":[]},"대상적격":{"d":"소송의 대상이 되는 처분등에 해당하는지 여부이다.","r":["원고적격","소의 이익"]},"원고적격":{"d":"소송을 제기해 본안 판단을 받을 수 있는 원고의 자격으로 취소소송에서는 법률상 이익이 있어야 한다.","r":["법률상 이익"]},"피고적격":{"d":"소송에서 피고가 될 수 있는 자격으로 항고소송에서는 원칙적으로 처분을 한 행정청이다.","r":["피고경정"]},"소의 이익":{"d":"소송으로 판결을 받아야 할 현실적 필요성과 법률상 이익이 있는지를 가리는 요건이다.","r":["법률상 이익"]},"제소기간":{"d":"소를 제기할 수 있는 기간으로 취소소송은 안 날부터 90일, 있은 날부터 1년 안에 제기해야 한다.","r":["불변기간"]},"행정심판전치":{"d":"행정소송을 제기하기 전에 먼저 행정심판을 거치도록 하는 제도로 법률에 규정이 있을 때만 요구된다.","r":[]},"당사자소송":{"d":"공법상 법률관계에 관해 그 법률관계의 한쪽 당사자를 피고로 하는 소송이다.","r":["항고소송"]},"가집행선고":{"d":"판결이 확정되기 전에도 집행할 수 있다고 선고하는 재판이다.","r":[]},"조리상 신청권":{"d":"법규에 명문 규정이 없어도 사리에 비추어 인정되는 처분 신청의 권리이다.","r":["거부처분"]},"거부처분":{"d":"개인의 처분 신청을 행정청이 받아들이지 않는 공권력 행사로 일정한 요건을 갖추면 항고소송의 대상이 된다.","r":["조리상 신청권"]},"경정처분":{"d":"이미 한 과세처분 등의 세액을 늘리거나 줄여 바로잡는 처분이다.","r":[]},"법률상 이익":{"d":"처분의 근거 법규와 관련 법규가 보호하는 개별적·직접적·구체적 이익이다.","r":["원고적격"]},"경업자":{"d":"같은 영업을 하는 경쟁 관계의 사업자로 기존 업자가 새 업자에 대한 처분을 다투는 경우에 문제된다.","r":[]},"피고경정":{"d":"원고가 피고를 잘못 지정했을 때 법원의 허가를 받아 피고를 바꾸는 제도이다.","r":["피고적격"]},"소송참가":{"d":"소송 결과로 이익이나 권리를 침해받을 제3자나 행정청이 법원의 결정으로 소송에 참여하는 제도이다.","r":[]},"관련청구소송":{"d":"처분과 관련된 손해배상·부당이득반환 청구처럼 취소소송과 함께 심리할 수 있는 소송이다.","r":[]},"불변기간":{"d":"법원이 늘이거나 줄일 수 없도록 법이 정한 기간이다.","r":["제소기간"]},"집행정지":{"d":"취소소송 중에 처분의 효력이나 집행, 절차 속행을 법원이 잠정적으로 멈추게 하는 결정이다.","r":["집행부정지 원칙"]},"집행부정지 원칙":{"d":"취소소송을 제기해도 처분의 효력이나 집행이 멈추지 않는다는 원칙이다.","r":["집행정지"]},"공공복리":{"d":"사회 전체의 공동 이익으로 이에 중대한 영향이 있으면 집행정지가 허용되지 않는다.","r":[]},"석명권":{"d":"법원이 당사자에게 진술의 모순이나 불명확을 바로잡게 하고 증거를 내도록 촉구하는 권한이다.","r":[]},"직권심리":{"d":"당사자가 주장하지 않은 사실도 법원이 직접 증거를 조사하고 판단하는 심리 방식이다.","r":["석명권"]},"일부취소":{"d":"처분이 나뉠 수 있고 취소할 부분을 특정할 수 있을 때 그 부분만 취소하는 판결이다.","r":[]},"기속력":{"d":"확정판결의 취지에 따라 행정청이 행동해야 하는 구속력으로 반복금지와 재처분의무를 낳는다.","r":["간접강제"]},"재처분의무":{"d":"거부처분이 취소되면 행정청이 판결 취지에 따라 신청에 대해 다시 처분해야 할 의무이다.","r":["기속력"]},"간접강제":{"d":"행정청이 재처분을 하지 않을 때 배상금 지급을 명해 심리적으로 이행을 압박하는 제도이다.","r":["기속력"]},"기판력":{"d":"확정판결의 내용이 같은 당사자 사이에서 다시 다투지 못하도록 구속하는 힘이다.","r":[]},"사정판결":{"d":"청구가 이유 있어도 처분 취소가 현저히 공공복리에 적합하지 않을 때 청구를 기각하는 판결이다.","r":["공공복리"]},"제3자 재심":{"d":"취소판결로 권리를 침해받은 제3자가 소송에 참가하지 못한 경우 확정판결의 재심을 구하는 제도이다.","r":[]},"불고불리 원칙":{"d":"법원이 당사자가 청구한 범위를 넘어 판결할 수 없다는 원칙이다.","r":[]},"변론관할":{"d":"관할이 없는 법원에서 피고가 이의 없이 본안 변론을 하면 그 법원에 관할이 생기는 것이다.","r":[]},"공정력":{"d":"하자가 있는 행정처분도 무효가 아니라면 취소되기 전까지 유효한 것으로 통용되는 힘이다.","r":[]},"불가쟁력":{"d":"제소기간이 지나 더는 처분을 다툴 수 없게 된 상태이다.","r":[]}},"notes":{"2026.3.17 신설된 제9조 제4항에 따라 법원조직법상 해사행정사건에 해당하는 취소소송은 피고 소재지를 관할하는 해사국제상사법원에 전속한다":"2026.3.17 신설된 제9조 제4항 때문에 해사행정사건의 취소소송은 피고 소재지 관할 해사국제상사법원 전속입니다.","90일은 불변기간이어서 법원이 늘이거나 줄일 수 없고 1년은 정당한 사유가 있으면 예외가 인정된다":"90일은 불변기간이라 법원이 조정하지 못하고, 1년은 정당한 사유가 있을 때 예외로 연장 효과를 인정합니다.","가분인 처분은 일부만 무효확인할 수 있다":"처분이 나뉠 수 있으면 일부만 무효확인을 구하는 것도 허용됩니다.","가중 제재 규정이 있는 의사면허자격정지는 정지기간이 지나도 소의 이익이 있다":"가중 제재 규정이 있으면 이미 끝난 의사면허자격정지도 이후 가중 처분의 기초가 되어 취소를 구할 소의 이익이 있습니다.","감사원 변상판정에 대한 재심의판정, 중앙노동위원회 재심판정, 특허심판원 심결은 재결을 대상으로 소를 낸다":"감사원 재심의판정, 중앙노동위원회 재심판정, 특허심판원 심결처럼 재결주의가 적용되는 경우에는 재결을 대상으로 소를 냅니다.","개별공시지가결정, 부담(부관)":"개별공시지가결정과 부담(부관)은 각각 독립적으로 법적 효과를 가져 처분성이 인정됩니다.","객관소송인 민중소송·기관소송은 법률이 정한 경우에 법률에 정한 자만 제기한다(제45조)":"민중소송과 기관소송은 객관소송이어서 법률에 허용 규정이 있을 때 그 규정에서 정한 사람만 제기할 수 있습니다.","거부가 처분이 되려면 신청한 행위가 공권력 행사이고 거부가 신청인의 법률관계에 영향을 주며 신청인에게 법규상 또는 조리상 신청권이 있어야 한다":"거부가 소송 대상인 처분이려면 세 가지가 갖춰져야 하며, 공권력 행사의 거부일 것, 법률관계에 영향이 있을 것, 신청권이 있을 것입니다.","거부처분, 입법부작위, 검사의 압수물 환부 부작위는 이 소송의 대상이 아니다":"거부처분이나 입법부작위, 검사의 압수물 환부 부작위는 처분을 할 법적 의무의 부작위가 아니어서 이 소송의 대상이 아닙니다.","거부처분은 정지해도 신청 전 상태로 돌아갈 뿐이어서 집행정지 대상이 아니다":"거부처분은 효력을 멈춰도 신청이 받아들여진 상태가 되지 않고 신청 전으로 돌아가는 데 그치므로 정지할 실익이 없습니다.","거부처분이 취소되면 행정청은 판결 취지에 따라 이전 신청에 대해 다시 처분해야 하고 신청에 따른 처분이 절차 위법으로 취소된 때도 같다(제30조 제2항·제3항)":"거부처분이 취소되면 행정청은 판결 취지에 따라 이전 신청을 다시 처분해야 하며, 절차 위법으로 취소된 때도 같습니다.","거부처분 취소소송과 계속효 있는 처분도 처분시가 기준이다":"거부처분 취소소송이나 계속적 효과가 있는 처분도 처분이 내려진 때를 기준으로 위법 여부를 판단합니다.","거부처분취소판결과 부작위위법확인판결에만 인정되고 무효확인판결·당사자소송에는 없으며 법원의 직접처분 제도는 없다":"간접강제는 거부처분취소판결과 부작위위법확인판결에만 인정되고, 법원이 행정청 대신 처분하는 직접처분 제도는 인정되지 않습니다.","건축공사가 완료된 뒤 이웃주민의 건축허가 취소청구, 인접주택 소유자의 사용승인 취소청구":"건축공사가 이미 끝난 뒤에는 이웃주민이 건축허가나 사용승인을 취소해도 얻는 이익이 없어 소의 이익이 없습니다.","건축신고 반려, 지목변경신청 반려, 토지대장 직권말소":"건축신고 반려, 지목변경신청 반려, 토지대장 직권말소는 국민의 법적 지위에 영향을 주어 처분으로 본 사례들입니다.","검사의 불기소처분과 공소제기는 형사절차로 다툰다":"검사의 불기소처분이나 공소제기는 행정소송이 아닌 형사절차의 틀 안에서 다투어야 합니다.","결과를 통지받은 날(기간 내 통지가 없으면 통지기간 만료 다음 날)부터 90일 이내에 행정심판이나 행정소송을 제기 · 이의신청과 관계없이 바로 소송을 낼 수도 있다":"이의신청 결과를 통지받은 날부터 90일 안에 심판이나 소송을 낼 수 있고, 이의신청을 거치지 않고 바로 소송을 내도 됩니다.","결정은 변론 없이 할 수 있고 민사집행법 제262조(채무자 심문)가 준용되며 효력은 행정청이 속한 국가 또는 공공단체에 미친다":"간접강제 결정은 변론 없이 가능하며 민사집행법 제262조의 심문 규정을 따르고, 그 효력은 행정청이 속한 국가나 공공단체에 미칩니다.","경원관계에서 불선정된 사업자는 자신에 대한 불선정처분의 취소를 구할 수 있다":"한 사업을 두고 경쟁하다 탈락한 경원자는 자신에 대한 불선정처분의 취소를 구할 법률상 이익이 있습니다.","경정청구기간이 지난 뒤의 경정청구, 불가쟁력이 생긴 처분의 변경신청, 토지대장 소유자명의변경신청":"경정청구기간 경과 후 청구, 불가쟁력이 생긴 처분의 변경신청, 토지대장 명의변경신청을 거부해도 처분성이 부정됩니다.","계약 불이행과 공무원에 대한 뇌물 제공, 무자료주류판매와 무면허업자에 대한 판매는 동일성이 없다":"계약 불이행과 공무원 뇌물 제공, 무자료주류판매와 무면허업자 판매는 사실관계가 달라 동일성이 없다고 본 사례입니다.","고시로 불특정다수에게 한 처분은 고시의 효력발생일에 알았다고 보고 특정인에 대한 처분을 주소불명으로 공고한 경우는 상대방이 현실적으로 안 날이 기준이다":"고시로 한 처분은 고시의 효력발생일에 안 것으로 보고, 주소불명으로 공고한 특정인 대상 처분은 상대방이 실제로 안 날이 기준입니다.","고유한 위법이 없는데 재결을 다투면 각하가 아니라 기각판결을 한다":"재결에 고유한 위법이 없는데 재결을 다투면 소송요건 흠이 아니라 본안 사유라서 각하가 아닌 기각판결을 합니다.","공개심리, 쌍방심리, 구술심리, 자유심증주의, 직권진행주의도 적용된다":"민사소송의 기본 원칙인 공개·쌍방·구술심리, 자유심증주의, 직권진행주의가 행정소송에도 그대로 통용됩니다.","공공복리에 중대한 영향을 미칠 우려가 있으면 허용되지 않고(제23조 제3항) 이 점은 행정청이 소명한다":"공공복리에 중대한 영향을 미칠 우려가 있으면 집행정지가 허용되지 않으며, 이 점은 행정청이 소명합니다.","공무수탁사인이나 사인도 피고가 될 수 있고 원고적격 규정은 따로 없다":"당사자소송에서는 사인이나 공무수탁사인도 피고가 될 수 있으며, 원고적격을 정한 별도 규정은 없습니다.","공법상 신분·지위 확인소송, 공법상 계약에 따른 의무 이행청구는 허용된다":"공법상 신분이나 지위를 확인하는 소송과 공법상 계약에 따른 의무 이행을 구하는 소송이 당사자소송으로 인정됩니다.","공장설립승인이 쟁송취소되어도 공장건축허가가 남아 있으면 인근 주민은 건축허가 취소를 구할 이익이 있다":"공장설립승인이 취소돼도 이미 받은 건축허가가 별개로 살아 있으면 인근 주민은 그 허가를 없애야 이익이 회복되므로 소의 이익이 있습니다.","공정거래위원회 고발조치, 공매통지, 국세환급금결정":"공정거래위원회의 고발조치, 공매통지, 국세환급금결정은 상대방의 법적 지위를 직접 정하지 않아 처분성이 부정됩니다.","공직선거법상 선거소송(선관위원장 피고, 대법원·고등법원 관할), 국민투표무효소송, 지방자치법상 주민소송이 해당한다":"공직선거법상 선거소송, 국민투표무효소송, 지방자치법상 주민소송이 민중소송에 해당합니다.","과세처분·개발부담금처럼 기속행위인 금전부과는 정당한 금액을 산출할 수 있으면 초과 부분만, 산출할 수 없으면 전부 취소한다":"과세처분 같은 기속행위는 정당한 금액을 산출할 수 있으면 초과분만, 산출할 수 없으면 전부 취소합니다.","과세처분 취소청구 기각판결의 기판력은 같은 처분의 무효확인소송에도 미치지만 취소판결이 곧바로 국가배상의 고의·과실까지 인정하지는 않는다":"취소 청구가 기각되면 같은 처분의 무효확인소송도 그 판단에 구속되지만, 취소판결만으로 국가배상의 고의·과실이 인정되지는 않습니다.","과징금 납부기한은 정지기간 동안 진행하지 않는다":"과징금 납부기한은 집행정지 기간 동안 흐르지 않고 멈춥니다.","과태료 부과는 질서위반행위규제법 절차로 다툰다":"과태료 부과는 질서위반행위규제법이 정한 별도 절차로 다투어야 하며 행정소송 대상이 아닙니다.","관계 법규의 해석으로 추상적으로 정하고, 인용될 수 있는지는 본안에서 판단한다":"신청권은 관계 법규를 해석해 추상적으로 정하며, 신청이 받아들여질지는 소송요건이 아니라 본안에서 판단합니다.","관련청구소송이 계속된 법원이 상당하다고 인정할 때 신청 또는 직권으로 취소소송이 계속된 법원으로 한다":"관련청구소송을 맡은 법원이 상당하다고 판단하면 신청이나 직권으로 그 사건을 취소소송이 진행 중인 법원으로 옮깁니다.","교원소청심사위원회 결정, 국가공무원법상 소청결정, 국세기본법상 심판결정, 토지수용 이의재결":"교원소청심사위원회 결정, 소청결정, 국세 심판결정, 토지수용 이의재결은 원처분주의가 적용되는 재결의 예입니다.","국가는 기관위임사무를 처리한 지방자치단체장을 상대로 취소소송을 낼 수 없다":"기관위임사무를 처리한 지방자치단체장은 국가의 하급기관이므로 국가가 그를 상대로 취소소송을 낼 수 없습니다.","국가 또는 공공단체의 기관 상호간 권한의 존부·행사에 관한 다툼에 대한 소송이고 헌법재판소 관장사항인 권한쟁의(지방자치단체 상호간 다툼 등)는 빠진다":"기관소송은 국가·공공단체 기관 사이의 권한 존부와 행사를 다투는 소송이며 헌법재판소 소관의 권한쟁의는 제외됩니다.","국가 또는 공공단체의 기관 상호간 권한의 존부·행사에 관한 다툼을 대상으로 하며 헌법재판소 관장사항인 권한쟁의는 빠진다":"기관소송은 공공기관 사이에서 권한이 있는지와 어떻게 행사하는지를 다투는 소송이며, 헌법재판소 소관인 권한쟁의는 제외됩니다.","국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때 자기의 법률상 이익과 관계없이 그 시정을 구하는 소송(제3조 제3호)":"민중소송은 기관의 법 위반 행위에 대해 자기의 법률상 이익과 관계없이 시정을 구하는 객관소송입니다.","국가 상대 당사자소송에서 가집행선고를 금지하던 제43조는 헌법재판소 위헌결정(2020헌가12)으로 효력을 잃었고 2026.5.12 삭제되었다":"2020헌가12 위헌결정으로 국가 상대 당사자소송의 가집행선고 금지 조항(제43조)이 효력을 잃고 2026.5.12 삭제되었습니다.","국가 상대 당사자소송의 가집행선고를 막던 제43조는 헌법재판소 위헌결정으로 효력을 잃고 2026.5.12 삭제되어 지금은 가집행선고를 할 수 있다":"국가를 상대로 한 당사자소송에서 가집행선고를 막던 조항이 위헌결정으로 효력을 잃고 2026.5.12 삭제되어 지금은 가집행선고가 가능합니다.","국가인권위원회 성희롱결정·시정조치권고, 금융감독원장의 문책경고":"국가인권위원회의 성희롱결정·시정조치권고와 금융감독원장의 문책경고는 상대방에게 불이익을 주는 처분입니다.","국민의 권리의무에 직접 영향을 주는지가 기준이어서 행정규칙에 근거한 행위라도 권리의무를 직접 바꾸면 처분":"처분 여부는 국민의 권리의무에 직접 영향을 주는지로 가리므로, 행정규칙에 근거한 행위도 권리의무를 직접 바꾸면 처분입니다.","국세(심사·심판청구), 지방세(조세심판원 심판청구 또는 감사원 심사청구), 국가공무원 징계(소청), 운전면허 처분":"국세, 지방세, 국가공무원 징계, 운전면허 처분은 소를 내기 전에 먼저 행정심판을 거쳐야 하는 대표 영역입니다.","국외에서의 소송행위추완은 14일을 30일로, 제3자 재심청구는 30일을 60일로, 소의 제기는 60일을 90일로 한다(제5조)":"제5조는 기간이 모자라는 국외 사정을 고려해 추완 14일을 30일로, 재심 30일을 60일로, 제소 60일을 90일로 늘립니다.","군의관의 병역법상 신체등위판정":"군의관이 병역법에 따라 내린 신체등위판정은 병역처분의 준비 단계로 보아 처분이 아닙니다.","권한을 위탁받은 사인, 지방법무사회, 국회의 기관도 처분을 하면 피고가 된다":"공무를 위탁받은 사인, 지방법무사회, 국회의 기관은 행정청이 아니더라도 처분을 하면 항고소송에서 피고 자격을 얻습니다.","그 자체가 피고이지만 중앙노동위원회 처분은 노동위원회법에 따라 위원장이 피고이다":"합의제 행정청은 원칙적으로 기관 자체가 피고이나 중앙노동위원회 처분만은 노동위원회법이 위원장을 피고로 정했습니다.","기간의 말일이 공휴일이면 다음 날 만료한다":"기간의 마지막 날이 공휴일이면 그 다음 날 기간이 끝납니다.","기속력, 제3자효, 제3자 재심, 간접강제, 재판관할, 직권심리, 재량처분 취소, 관련청구 이송·병합은 준용된다(제38조 제2항)":"부작위위법확인소송에는 기속력, 제3자효, 제3자 재심, 간접강제, 재판관할, 직권심리, 재량처분 취소, 관련청구 이송·병합이 준용됩니다.","기속력에 반하는 처분은 하자가 중대·명백하여 당연무효이고 취소판결 확정 후 그 처분을 경정한 처분도 무효이다":"기속력에 어긋난 처분은 하자가 중대하고 명백해 당연무효이며, 취소판결 확정 후 그 처분을 고친 경정처분도 무효입니다.","기속력은 종전 처분 당시까지의 사유에만 미쳐 처분 후의 새 사유나 개정 법령, 기본적 사실관계가 다른 사유로 다시 거부할 수 있다":"기속력은 종전 처분 당시까지의 사유에만 미쳐, 처분 후의 새 사유나 개정 법령이 있으면 다시 거부할 수 있습니다.","기존 담배 일반소매인, 노선이 겹치는 기존 버스·화물운송사업자, 영업지역 내 이전을 다투는 기존 약종상은 신규 업자에 대한 수익적 처분을 다툴 원고적격이 있다":"이미 영업 중인 업자가 신규 업자에게 준 수익적 처분을 다툴 때 담배소매인, 겹치는 노선의 운송업자, 약종상은 법률상 이익이 인정됩니다.","기존 일반소매인이 신규 구내소매인 지정을 다투는 경우와 경업자에게 불리한 처분을 다투는 경우는 원고적격이 없다":"기존 소매인이 구내소매인 신규 지정을 다툴 때와 경업자에게 불리한 처분을 다툴 때는 보호되는 법률상 이익이 없어 원고적격이 부정됩니다.","기준시는 처분시이지만 법원은 사실심 변론종결시까지 제출된 모든 자료로 처분 당시의 객관적 사실을 확정한다":"판단 기준 시점은 처분이 내려진 때이지만 증거는 변론이 끝날 때까지 낸 것을 모두 보아 그 당시의 사실을 확정합니다.","내부위임을 받은 기관이 자기 이름으로 처분하면 그 기관이, 대리관계를 밝혀 처분하면 피대리청이 피고이다":"내부위임을 받은 기관이 위임청 이름이 아닌 자기 이름으로 처분하면 그 기관이, 위임청 이름으로 했다면 위임한 행정청이 피고입니다.","다른 법률에 재결을 거치도록 한 경우":"다른 법률이 재결을 거치도록 정한 때에는 행정심판을 먼저 거쳐야 하는 필요적 전치가 적용됩니다.","다른 행정청의 참가도 신청 또는 직권으로 하며 행정청은 민사소송법상 보조참가를 할 수 없지만 제3자는 요건을 갖추면 보조참가도 할 수 있다":"다른 행정청 참가는 신청이나 직권으로 가능하며, 행정청은 민사 보조참가를 못 하나 제3자는 요건이 되면 보조참가도 할 수 있습니다.","당사자소송에는 제20조가 준용되지 않고 법령에 기간이 있으면 그 기간이 불변기간이다(제41조)":"당사자소송에는 제소기간에 관한 제20조가 준용되지 않고, 법령에 정해진 기간이 있으면 그 기간이 불변기간입니다.","당사자소송의 피고는 행정청이 아니라 국가·공공단체 그 밖의 권리주체이다(제39조)":"당사자소송의 피고는 행정청이 아니라 국가·공공단체 그 밖의 권리주체이며 이 점이 항고소송과 다릅니다.","당초 처분은 증액경정처분에 흡수되어 증액경정처분이 소송 대상이다":"증액경정처분이 있으면 당초 처분은 그 안에 흡수되어 소멸하므로 소송 대상은 증액경정처분입니다.","당초 처분 중 감액되지 않고 남은 부분이 대상이다":"감액경정에서는 당초 처분 중 감액되지 않고 남은 부분이 소송 대상이 됩니다.","당해 처분과 관련되는 손해배상·부당이득반환·원상회복 청구와 관련 취소소송이 관련청구소송이다(제10조)":"관련청구소송은 처분과 관련된 손해배상·부당이득반환·원상회복 청구와 관련 취소소송을 가리킵니다.","대법원 전원합의체 판결(2007두6342)은 민사소송의 확인의 이익, 즉 보충성이나 즉시확정의 이익을 요구하지 않는다":"대법원 전원합의체 2007두6342는 무효확인소송에서 민사 확인소송처럼 즉시확정의 이익이나 보충성을 따지지 않는다고 판시했습니다.","대법원판결로 명령·규칙이 헌법 또는 법률에 위반된다고 확정되면 대법원은 지체 없이 행정안전부장관에게 통보하고 장관은 관보에 게재한다(제6조)":"대법원에서 명령·규칙이 위헌·위법으로 확정되면 대법원이 행정안전부장관에게 알리고 장관은 이를 관보에 실어야 합니다.","대상이 처분이 아니라 공법상 법률관계라는 점에서 항고소송과, 공법관계라는 점에서 민사소송과 구별된다":"당사자소송은 대상이 처분이 아닌 공법상 법률관계이므로 항고소송과 다르고, 공법관계를 다루므로 민사소송과도 구별됩니다.","대상적격, 원고적격, 피고적격, 소의 이익, 제소기간, 필요한 경우 행정심판전치는 법원의 직권조사사항이다":"대상적격·원고적격·피고적격·소의 이익·제소기간 등 소송요건은 당사자가 다투지 않아도 법원이 스스로 조사해야 하는 사항입니다.","대학교 총학생회는 임시이사선임처분을 다툴 수 있다":"총학생회는 임시이사를 선임한 처분에 대해 법률상 이익이 있어 원고적격이 인정된 사례입니다.","대학 직원 노동조합, 대한의사협회(상대가치점수 고시), 한약조제시험 합격처분을 다투는 한의사":"대학 직원 노동조합, 대한의사협회, 한약조제시험 합격처분을 다투는 한의사도 원고적격이 부정되었습니다.","도시기본계획, 4대강 마스터플랜, 혁신도시 최종입지선정":"도시기본계획, 4대강 마스터플랜, 혁신도시 최종입지선정은 국민의 권리의무를 직접 바꾸지 않아 처분이 아닌 예입니다.","동일성은 법적 평가가 아니라 사회적 사실관계를 기준으로 하며 처분시에 존재하던 사유만 추가할 수 있다":"동일성은 법적 평가가 아닌 사회적 사실관계로 판단하고, 처분 당시 이미 있던 사유만 소송 중에 보태 쓸 수 있습니다.","두 소송은 관련청구소송이어서 병합할 수 있다":"보상금증감청구소송과 재결취소소송은 서로 관련청구소송이어서 병합할 수 있습니다.","두 청구는 양립할 수 없어 주위적·예비적 병합만 되고 단순·선택적 병합은 안 된다":"무효확인과 취소 청구는 서로 양립할 수 없는 관계여서 주위적·예비적으로만 묶고 단순·선택적 병합은 인정되지 않습니다.","무효등 확인소송에는 제소기간(제20조)과 행정심판 전치(제18조)가 준용되지 않아 행정심판을 거쳤더라도 기간 제한이 없다":"무효등 확인소송은 제소기간과 행정심판 전치 규정이 적용되지 않아, 행정심판을 거친 경우에도 제소기간에 제한받지 않습니다.","무효를 선언하는 의미의 취소소송은 취소소송이므로 제소기간과 전치요건을 갖추어야 한다":"무효를 선언하는 의미의 취소소송은 이름과 달리 취소소송이어서 제소기간과 전치요건을 모두 갖춰야 합니다.","무효 사유의 증명책임은 원고에게 있다":"무효의 사유가 있다는 점은 무효를 주장하는 원고가 증명해야 합니다.","무효확인·부작위위법확인소송에는 준용되지 않고 원고는 손해배상 등을 병합할 수 있으며 소송비용은 피고가 부담한다":"사정판결은 무효확인·부작위위법확인소송에 쓰이지 않으며, 원고는 손해배상 등을 병합할 수 있고 비용은 피고 부담입니다.","무효확인·부작위위법확인소송에 준용되고 당사자소송에는 준용되지 않는다":"재심청구 규정은 무효확인소송과 부작위위법확인소송에는 준용되지만 당사자소송에는 준용되지 않습니다.","무효확인소송에는 제소기간이 없지만 무효선언을 구하는 취소소송은 제소기간과 전치요건을 갖추어야 한다":"무효확인소송은 제소기간이 없으나 무효를 선언하는 취소소송은 취소소송이므로 제소기간과 전치요건을 지켜야 합니다.","무효확인의 소가 취소소송 제소기간 안에 제기되었다면 나중에 추가 병합한 취소청구도 적법하다":"무효확인의 소가 취소소송 제소기간 안에 제기됐다면 뒤에 추가 병합한 취소청구도 기간을 지킨 적법한 청구입니다.","무효확인청구에는 특별한 사정이 없는 한 취소를 구하는 취지도 포함되어 있어 무효사유가 증명되지 않아도 취소소송 요건을 갖추었으면 취소사유를 심리해야 한다":"무효확인 청구에는 취소를 구하는 취지가 포함되어 있어, 무효 증명에 실패해도 취소소송 요건을 갖췄다면 취소사유를 따져야 합니다.","민사사건을 당사자소송으로 행정법원에 냈는데 피고가 항변 없이 본안 변론을 하면 변론관할이 생긴다":"당사자소송으로 냈지만 실질은 민사사건인데 피고가 이의 없이 본안을 다투면 원래 관할이 없던 행정법원에도 변론관할이 생깁니다.","민주화운동관련자 보상심의위원회의 지급 기각결정, 산업단지관리공단의 입주계약 취소, 국유재산 변상금 부과는 처분이어서 항고소송으로 다툰다":"민주화운동관련자 지급 기각결정, 입주계약 취소, 국유재산 변상금 부과는 처분이어서 당사자소송이 아니라 항고소송으로 다툽니다.","민중·기관소송 중 취소를 구하면 취소소송, 무효·부작위 확인을 구하면 그 소송, 나머지는 당사자소송 규정을 성질에 반하지 않는 한 준용한다(제46조)":"민중·기관소송은 구하는 내용에 따라 취소소송, 무효·부작위 확인소송, 당사자소송 규정 중 맞는 규정을 성질에 어긋나지 않게 준용합니다.","반복된 제2차 계고와 반복된 독촉은 새 의무를 부과하지 않음":"이미 계고나 독촉을 한 뒤 되풀이한 것은 새로운 의무를 부과하지 않아 독립한 처분이 아닙니다.","발송일이나 심판청구일이 아니다":"행정심판을 거친 경우의 기산일은 재결서를 받은 날이지, 재결서가 발송된 날이나 심판청구일이 아닙니다.","배상금은 제재나 손해배상이 아니라 재처분을 하게 하는 심리적 강제수단이다":"간접강제 배상금은 제재나 손해배상이 아니라 재처분을 하도록 심리적으로 압박하는 수단입니다.","법령에 제소기간이 있으면 불변기간이고(제41조) 항고소송으로 소 변경이 가능하다(제42조)":"법령에 제소기간이 있으면 그 기간은 불변기간이고, 당사자소송을 항고소송으로 변경하는 것도 가능합니다.","법률이 정한 경우에 법률에 정한 자만 제기한다(제45조)":"민중소송은 법률이 허용한 경우에 그 법률이 정한 사람만 제기할 수 있습니다.","법원은 소송 결과로 권리 또는 이익을 침해받을 제3자를 당사자·제3자의 신청 또는 직권으로 참가시킬 수 있고 미리 당사자와 제3자의 의견을 듣는다(제16조)":"법원은 소송 결과로 권리나 이익을 침해받을 제3자를 직권이나 신청으로 참가시킬 수 있고 미리 당사자와 제3자의 의견을 듣습니다.","법원은 제출 자료로 정당한 세액을 직권으로 산출할 수 있다":"법원은 제출된 자료로 정당한 세액을 직접 계산해 판단할 수 있습니다.","법원은 필요하면 직권으로 증거조사를 하고 당사자가 주장하지 않은 사실도 판단할 수 있지만(제26조) 기록상 나타난 사항에 한한다":"법원은 필요하면 직권으로 증거를 조사하고 당사자가 주장하지 않은 사실도 판단할 수 있으나, 그 범위는 기록에 나타난 사항으로 한정됩니다.","변경된 소는 처음 소를 제기한 때에 제기된 것으로 본다":"소의 종류를 변경하면 변경된 소는 처음 소를 낸 때 제기된 것으로 봅니다.","본안소송은 소송요건을 갖춘 적법한 것이어야 하고 본안이 계속 중이라는 점은 신청인이 주장·소명한다":"집행정지를 받으려면 본안소송이 적법해야 하고, 본안이 계속 중이라는 사실은 신청한 사람이 주장하고 소명해야 합니다.","본안소송이 취하되면 별도 결정 없이 집행정지의 효력이 소멸하고 본안판결 선고로도 소멸한다":"본안소송이 취하되면 집행정지는 따로 결정하지 않아도 효력이 소멸하고, 본안판결이 선고되어도 소멸합니다.","본안이 계속 중이고 처분등의 존재, 회복하기 어려운 손해, 이를 예방할 긴급한 필요가 있어야 한다":"집행정지는 본안이 계속 중이고 처분등이 있으며 회복하기 어려운 손해를 예방할 긴급한 필요가 있어야 인정됩니다.","부가가치세 환급세액 지급청구, 명예퇴직 법관의 미지급 수당 청구, 지방소방공무원의 초과근무수당 청구, 공무원 지위 확인, 시립무용단원 해촉·시립합창단원 재위촉 거부·공중보건의사 채용계약 해지, 보조금 교부조건에 따른 반환청구, 국가의 조세채권존재확인":"환급세액 지급청구, 미지급 수당 청구, 공무원 지위 확인, 보조금 반환청구 등은 공법관계에서 생긴 청구여서 당사자소송으로 인정됩니다.","부가가치세 환급청구나 납세의무부존재확인은 세무서장이 아니라 국가가 피고이고 세무서장을 피고로 했으면 피고경정을 허가할 수 있다":"부가가치세 환급청구는 세무서장이 아닌 국가가 피고이고, 세무서장을 잘못 피고로 삼았으면 피고경정을 허가할 수 있습니다.","부작위만 대상으로 하고 거부처분은 취소소송이나 무효확인소송으로 다툰다":"부작위위법확인소송은 아무 처분이 없는 부작위만 다루고, 이미 내려진 거부처분은 취소소송이나 무효확인소송의 대상입니다.","부작위위법확인소송과 당사자소송에는 준용되지 않는다":"집행정지는 항고소송 중 부작위위법확인소송과 당사자소송에는 적용되지 않는다는 점이 한계입니다.","부작위위법확인소송은 처분이 없으므로 재결을 거쳤는지와 관계없이 사실심 변론종결시가 기준이다":"부작위위법확인소송은 처분이 없는 상태를 다투므로 재결 유무와 상관없이 사실심 변론종결 때가 기준입니다.","부작위위법확인소송은 행정심판을 거쳤다면 재결서 정본 송달일부터 90일의 제한을 받는다":"행정심판을 거쳤다면 부작위위법확인소송도 재결서 정본을 받은 날로부터 90일 안에 제기해야 하는 제한을 받습니다.","불고불리 원칙이 적용되어 법원은 원고의 청구범위를 넘어 인용하거나 청구하지 않은 처분을 취소할 수 없다":"법원은 원고가 청구하지 않은 것은 판단하지 못하므로 청구 범위를 넘는 인용이나 청구하지 않은 처분의 취소는 안 됩니다.","사립학교 교원 징계는 학교법인의 사법상 행위여서 소청심사위원회 결정이 처분으로서 소송 대상이 된다":"사립학교 교원 징계는 학교법인의 사법상 행위이므로 소청심사위원회 결정이 처분이 되어 그 결정이 소송 대상입니다.","사실관계가 같으면 근거법령만 바꾸거나 추가할 수 있고 불명확한 당초 사유를 구체적으로 설명하는 것은 새 사유가 아니다":"사실관계가 같으면 법령만 바꾸거나 불명확한 이유를 풀어 쓰는 것은 새 사유의 추가가 아니라서 허용됩니다.","사실심 변론종결시까지 피고 외의 자를 상대로도 할 수 있고 본래의 취소소송이 각하되면 병합된 관련청구도 각하된다":"병합은 사실심 변론종결 때까지 가능하며 본래의 취소소송이 각하되면 병합된 관련청구도 함께 각하됩니다.","사실심 변론종결시까지 할 수 있고 새 피고에 대한 소는 처음 소를 제기한 때에 제기된 것으로, 종전 피고에 대한 소는 취하된 것으로 본다":"피고경정은 사실심 변론종결 때까지 가능하며 새 피고에 대한 소는 처음 제기 때 낸 것으로, 종전 피고에 대한 소는 취하된 것으로 봅니다.","사실심 변론종결시를 기준으로 주문에 포함된 처분의 위법성 존부 판단에만 생기고 처분이 귀속하는 국가·공공단체에도 미친다":"기판력은 변론이 끝난 시점의 처분 위법성 판단에만 생기며, 처분이 귀속하는 국가나 공공단체에도 그 효력이 미칩니다.","사실적·경제적 이해관계나 명예 같은 인격적 이익만으로는 부족하고 이는 무효등 확인소송도 같다":"사실적·경제적 이해관계나 명예 같은 인격적 이익만으로는 법률상 이익이 아니며 무효등 확인소송에서도 같습니다.","사업양도가 무효라고 주장하는 양도인은 지위승계신고 수리처분을 다툴 수 있다":"사업양도가 무효라고 주장하는 양도인은 양수인의 지위승계신고를 수리한 처분의 취소를 구할 이익이 있습니다.","사정판결이나 행정청의 처분 취소·변경으로 각하·기각된 경우 소송비용은 피고가 부담한다(제32조)":"사정판결이나 행정청의 처분 취소·변경으로 각하·기각될 때는 원고가 아니라 피고가 소송비용을 부담합니다.","산림형질변경 불허가에서 준농림지역 행위제한과 중대한 공익상 필요는 동일성이 있다":"산림형질변경 불허가에서 준농림지역 행위제한과 중대한 공익상 필요는 같은 사실관계에서 나온 사유라서 동일성이 인정됩니다.","상고심에서 흠결되면 소는 부적법해진다":"상고심에서 원고적격이 없어지면 소 전체가 부적법해집니다.","새로운 청구나 주장하지 않은 요건사실·공격방어방법을 권유하면 석명권의 한계를 넘는다":"법원이 새 청구를 하라고 권하거나 주장 안 한 요건사실을 제시하게 하면 당사자 주도 원칙을 침해해 석명권 범위를 벗어납니다.","새 사유로 직위해제를 다시 하면 이전 직위해제는 효력을 잃어 다툴 이익이 없고 소송 중 처분이 직권취소된 경우도 같다":"새 사유로 직위해제를 다시 하면 앞 처분은 효력을 잃어 소의 이익이 없고, 소송 중 처분이 직권취소돼도 마찬가지입니다.","새 시험에 합격한 뒤 이전 불합격처분 취소청구, 대집행 완료 후 계고처분 취소청구":"새 시험에 합격한 뒤의 이전 불합격처분 취소와 대집행이 끝난 뒤의 계고처분 취소는 회복될 이익이 없어 소의 이익이 부정됩니다.","생태·자연도 등급 변경을 다투는 인근 주민과 환경상 이익을 주장하는 재단법인 수녀원":"생태·자연도 등급 변경을 다투는 인근 주민이나 환경상 이익을 내세운 재단법인 수녀원은 원고적격이 없다고 본 사례입니다.","석명권은 진술의 모순·불명확을 보완하게 하거나 입증을 촉구하는 범위에서 행사한다":"석명권은 진술이 모순되거나 불명확할 때 보완하게 하거나 증거를 내라고 촉구하는 범위 안에서 행사합니다.","세무조사결정, 소득금액변동통지, 결손금 감액경정 통지":"세무조사결정, 소득금액변동통지, 결손금 감액경정 통지는 납세자에게 직접 법적 효과를 주는 처분으로 인정된 예입니다.","소의 종류 변경이나 이송 후 취소소송으로 바꾼 경우에는 처음 소를 제기한 때를 기준으로 한다":"소의 종류를 변경하거나 이송 뒤 취소소송으로 바꾼 경우에는 처음 소를 제기한 때를 기준으로 제소기간을 지킨 것으로 봅니다.","소 제기 전에는 집행정지를 할 수 없고 본안이 계속된 법원이 관할하므로 본안이 상급심에 있으면 그 법원이 결정한다":"소송을 내기 전에는 집행정지를 신청할 수 없고, 본안 사건이 있는 법원이 맡으므로 상급심에 가 있으면 그 상급 법원이 결정합니다.","소 제기 전후를 통해 판결시까지 행정청이 인용이든 거부든 처분을 하면 부작위가 해소되어 소는 각하된다":"판결 시까지 행정청이 인용이든 거부든 처분을 하면 부작위가 해소돼 소의 이익이 없어지므로 소를 각하합니다.","소 제기 후 처분이 변경되면 처분 변경을 안 날부터 60일 이내에 신청해야 한다(제22조)":"소를 제기한 뒤 처분이 변경되면 처분 변경을 안 날로부터 60일 안에 소 변경을 신청해야 합니다.","수소법원이 항고소송 관할도 가지고 있으면 행정소송으로 심리해야 한다":"소를 받은 법원이 항고소송 관할도 가지고 있다면 민사로 처리하지 않고 행정소송으로 심리해야 합니다.","수용재결 취소소송·이의재결 취소소송은 토지수용위원회가 피고이다":"수용재결이나 이의재결의 취소를 구하는 소송은 토지수용위원회를 피고로 합니다.","신청 각하결정에는 즉시항고할 수 있고 권한 승계·행정청 소멸로 인한 경정은 직권으로도 한다":"피고경정 신청을 각하한 결정에는 즉시항고가 가능하고, 권한 승계나 행정청 소멸에 따른 경정은 직권으로도 합니다.","신청인에게 법규상 또는 조리상 신청권이 있어야 하고 그 존부는 소송요건 단계에서 판단하지만 신청 내용이 적법할 필요는 없다":"부작위가 인정되려면 신청인에게 법규상이나 조리상 신청권이 있어야 하며, 그 존부는 소송요건에서 보고 신청 내용이 적법할 필요는 없습니다.","심리는 부작위의 위법 여부에 그치고 작위의무의 이행이나 특정 처분의무까지 구할 수 없다":"심리 범위는 부작위가 위법한지에 그치며 작위의무의 이행이나 특정 처분을 하라는 의무까지 구할 수는 없습니다.","심판청구 자체 없이 소를 낼 수 있는 경우: 동종사건에 이미 기각재결이 있을 때, 관련 처분 하나가 재결을 거쳤을 때, 행정청이 거칠 필요가 없다고 잘못 알린 때 등이며 그 사유는 원고가 소명한다":"동종사건 기각재결, 관련 처분의 재결 경유, 행정청의 잘못된 안내가 있으면 심판청구 없이 소를 낼 수 있고 사유는 원고가 소명합니다.","안 날은 유효한 처분이 있음을 현실적으로 안 날이고 있은 날은 처분의 효력이 발생한 날이다":"안 날은 처분이 있음을 실제로 알게 된 날이고, 있은 날은 처분의 효력이 발생한 날로 서로 다른 기산점입니다.","압류 후 압류부동산을 매수한 자는 압류처분 취소를 구할 원고적격이 없다":"압류 뒤에 압류부동산을 산 사람은 압류처분의 취소를 구할 원고적격이 없습니다.","영업정지·과징금은 법원이 적정한 정도를 정할 수 없어 법정 한도를 넘은 경우라도 전부 취소한다":"영업정지나 과징금 같은 재량행위는 법원이 적정 수준을 정할 수 없어 법정 한도를 넘으면 전부 취소합니다.","예외로 법원이 집행정지를 결정":"집행부정지 원칙의 예외로 법원이 직접 집행정지를 결정할 수 있습니다.","요건을 갖추지 못한 부적법한 신청은 각하한다":"요건을 못 갖춘 부적법한 집행정지 신청은 각하합니다.","요건이 빠지면 처분이 위법해도 각하판결을 하고, 원고는 요건을 보완해 다시 소를 낼 수 있다":"소송요건이 갖춰지지 않으면 처분이 위법해도 각하하며, 원고는 흠을 고쳐 다시 소를 제기할 수 있습니다.","운전면허 벌점 배점, 당연퇴직 인사발령, 군의관 신체등위판정":"운전면허 벌점 배점, 당연퇴직 인사발령, 군의관 신체등위판정은 내부 절차이거나 법적 효과가 이미 생겨 있어 처분이 아닙니다.","원고가 피고를 잘못 지정하면 법원은 원고의 신청으로 결정하여 피고경정을 허가하고 직권으로는 하지 못한다(제14조)":"피고를 잘못 지정한 원고의 신청에 법원이 결정으로 피고경정을 허가하며, 법원이 직권으로 하지는 못합니다.","원고의 고의 또는 중대한 과실 없이 심급을 달리하는 법원에 잘못 제기하거나 행정소송을 민사소송으로 잘못 제기하면 각하하지 않고 관할법원에 이송한다(제7조)":"원고에게 고의나 중대한 과실이 없는 관할 잘못이나 행정소송과 민사소송을 혼동한 경우에는 각하하지 않고 관할법원에 이송합니다.","위법성은 처분시, 공공복리 적합성은 사실심 변론종결시가 기준이고 신청 없이 직권으로도 하며 극히 엄격하게 적용한다":"사정판결에서 위법성은 처분시, 공공복리 적합성은 변론종결시가 기준이며 직권으로도 할 수 있으나 극히 엄격하게 적용합니다.","위법판단 기준시는 사실심 변론종결시이다":"부작위위법확인소송은 사실심 변론종결 때를 기준으로 위법 여부를 판단합니다.","응답을 받을 권리이지 인용을 받을 권리가 아니다":"신청권은 응답을 받을 권리일 뿐 신청한 내용대로 인용받을 권리가 아닙니다.","이때 행정소송규칙 제17조에 따라 소송비용의 전부 또는 일부를 피고에게 부담시킬 수 있다":"부작위가 해소돼 각하되더라도 행정소송규칙 제17조에 따라 소송비용의 전부 또는 일부를 피고가 부담하게 할 수 있습니다.","이행기간이 지난 뒤라도 재처분을 하면 더 이상 추심할 수 없다":"지연배상금은 이행 압박 수단이어서 이행기간이 지나도 재처분을 하면 그 이후에는 배상금을 받아 낼 수 없습니다.","이행소송 같은 직접적 구제수단이 있어도 무효확인을 구할 수 있다":"이행소송 같은 직접 구제수단이 있더라도 무효확인소송을 별도로 제기할 수 있다는 의미입니다.","인가·고시 전 재건축·재개발조합 총회결의의 효력을 다투는 소송":"재건축·재개발조합의 총회결의를 인가·고시 이전에 다투는 소송은 공법상 법률관계를 다투는 당사자소송으로 봅니다.","인가·고시 후의 관리처분계획은 항고소송으로 다투고 조합과 조합장 사이 선임·해임 관계와 조합임원 선임결의 무효확인, 환매권 존부 확인은 민사소송이다":"인가·고시 후의 관리처분계획은 항고소송으로 다투고, 조합 내부의 선임·해임 관계나 환매권 존부 확인은 민사소송입니다.","인용판결에만 생기고 각하·기각판결과 사정판결에는 없으며 무효확인판결과 당사자소송 판결에는 준용된다":"기속력은 처분을 취소하는 인용판결에서만 발생하므로 각하·기각·사정판결에는 없고, 무효확인판결과 당사자소송 판결에는 준용됩니다.","입국금지결정(외부에 통지되지 않은 내부 결정), 금융감독위원회의 파산신청":"입국금지결정이 외부에 통지되지 않은 내부 결정이면 처분이 아니며, 금융감독위원회의 파산신청도 처분이 아닙니다.","작위의무확인소송은 허용되지 않는다":"행정청에 작위의무가 있음을 확인해 달라는 작위의무확인소송은 허용되지 않습니다.","재결 없이 소를 낼 수 있는 경우: 청구 후 60일이 지나도 재결이 없을 때, 중대한 손해를 막을 긴급한 필요가 있을 때 등":"청구 뒤 60일이 지나도 재결이 없거나 중대한 손해를 막을 긴급한 필요가 있으면 재결 없이도 소를 낼 수 있습니다.","재결에 따른 후속처분이 아니라 거부처분을 취소한 재결 자체를 다투는 것":"후속처분이 아니라 거부처분을 취소한 재결 자체를 다투는 것은 소의 이익이 없습니다.","재결을 거쳐도 원칙적으로 원처분을 다투고, 변경재결이 있으면 변경된 원처분을 대상으로 원처분청을 피고로 한다":"재결을 거친 뒤에도 소송 대상은 처분 자체이며, 변경재결이 났다면 변경된 내용의 처분이 대상이고 피고는 그 처분청입니다.","재량권 일탈·남용, 비과세·면제 사유, 무효확인소송의 무효 사유는 원고가 증명한다":"재량권 일탈·남용, 비과세·면제 사유, 무효 사유는 원고에게 유리한 사실이어서 원고가 증명책임을 집니다.","재량처분이라도 재량권의 한계를 넘거나 남용이 있으면 법원이 취소할 수 있다(제27조)":"재량처분이라도 재량권의 한계를 넘거나 남용하면 위법해지므로 법원이 이를 이유로 취소할 수 있습니다.","재임용을 거부하는 취지의 임용기간만료 통지":"재임용을 거부하겠다는 취지로 보낸 임용기간만료 통지는 교원의 신분 상실을 가져오므로 처분입니다.","재조사결정에 따른 소송의 제소기간은 후속 처분의 통지를 받은 날부터 기산한다":"재조사결정에 따른 후속 처분이 있으면 그 처분의 통지를 받은 날부터 제소기간을 셉니다.","재판관할, 관련청구 이송·병합, 피고적격, 공동소송, 제3자·행정청 소송참가, 처분변경으로 인한 소의 변경, 집행정지, 제3자효, 기속력, 제3자 재심이 준용된다(제38조 제1항)":"무효등 확인소송에는 재판관할, 관련청구 이송·병합, 피고적격, 공동소송, 참가, 소 변경, 집행정지, 제3자효, 기속력 등이 준용됩니다.","적법한 심판청구를 각하한 재결, 심판 대상이 아닌 관념의 통지에 대한 인용재결이 그 예이다":"적법한 심판청구를 각하한 재결과 심판 대상이 아닌 관념의 통지에 대한 인용재결은 재결 자체의 위법으로 인정된 예입니다.","전치 요건은 사실심 변론종결시까지 갖추면 되고 전심에서 하지 않은 주장도 소송에서 할 수 있다":"전치 요건은 변론이 끝날 때까지만 채우면 흠이 치유되고, 전심 단계에서 내지 않았던 주장도 소송에서는 새로 펼 수 있습니다.","절차 위법으로 취소되면 적법한 절차를 거쳐 같은 내용의 처분을 할 수 있다":"절차 위법만이 취소 이유였다면 행정청은 올바른 절차를 거쳐 실질은 같은 처분을 다시 할 수 있습니다.","제3자의 심판청구로 인용재결이 나와 비로소 권리를 침해받은 처분 상대방은 인용재결의 취소를 구할 수 있고 피고는 행정심판위원회이다":"제3자 청구로 인용재결이 나 처음 불이익을 입은 상대방은 재결 자체가 위법의 원인이므로 인용재결 취소를 구하고 행정심판위원회를 피고로 삼습니다.","제소기간, 원고적격, 대상적격, 소의 이익, 전심절차 준수 같은 소송요건":"제소기간, 원고적격, 대상적격, 소의 이익, 전심절차 준수는 당사자가 다투지 않아도 법원이 조사하는 소송요건입니다.","제소기간, 전치, 사정판결, 간접강제는 준용되지 않아 거부처분 무효확인판결에는 재처분의무만 있고 간접강제는 없다":"무효확인판결에는 제소기간, 전치, 사정판결, 간접강제 규정이 준용되지 않아 거부처분 무효확인판결은 재처분의무만 있습니다.","제소기간, 집행정지, 제3자효, 제3자 재심, 간접강제는 준용되지 않고 대신 민사집행법상 가처분이 준용된다":"당사자소송은 제소기간, 집행정지, 제3자효, 제3자 재심, 간접강제가 없어 항고소송과 다르고 집행정지 자리에 민사집행법 가처분이 들어갑니다.","제소기간 준수 여부는 직권조사사항이다":"제소기간을 지켰는지는 법원이 직권으로 조사해야 하는 사항입니다.","제재처분은 처분시 시행령이 불리하게 바뀌었으면 행위시 시행령을 적용한다":"제재처분 뒤에 시행령이 불리하게 바뀌었다면 위반 행위가 있던 때의 시행령을 적용해 유리하게 처리합니다.","제재처분을 유리하게 바꾼 변경처분도 변경된 내용의 당초 처분이 대상이다":"제재를 유리하게 바꾼 변경처분이 나와도 다툴 대상은 변경된 내용으로 남은 당초 처분입니다.","제한 취지는 상대방의 방어권 보장과 신뢰보호이다":"처분사유의 추가를 제한하는 이유는 상대방의 방어권을 보장하고 신뢰를 보호하기 위해서입니다.","조례·고시도 집행행위 없이 직접 권리의무를 규율하면 처분":"조례나 고시가 집행행위 없이 곧바로 국민의 권리의무를 규율하면 처분으로 인정됩니다.","조례나 고시라도 집행행위 없이 그 자체로 직접 국민의 구체적 권리의무를 규율하면 처분이 되어 취소소송·무효확인소송의 대상이 된다":"조례·고시도 별도 집행 없이 곧바로 국민 권리를 정하면 규범이 아닌 처분으로 취급되어 취소소송과 무효확인소송으로 다툴 수 있습니다.","조례는 공포한 지방자치단체장이, 교육조례는 교육감이 피고이고 지방의회는 피고가 아니다":"조례를 공포한 사람이 피고이므로 일반 조례는 지방자치단체장, 교육조례는 교육감이며 조례를 의결한 지방의회는 피고가 아닙니다.","조세소송의 소송물은 과세단위별 개개의 부과처분이고 과세관청은 사실심 변론종결시까지 세액의 정당성을 뒷받침할 새 자료를 낼 수 있다":"조세소송은 과세단위별 개별 부과처분이 소송물이어서 과세관청이 변론종결 때까지 세액의 정당성을 뒷받침할 새 자료를 낼 수 있습니다.","주문뿐 아니라 이유 중 구체적 위법사유의 판단에도 미치고 행정청은 위법한 결과를 제거할 의무를 진다":"기속력은 판결 주문뿐 아니라 이유 중 구체적 위법사유 판단에도 미치고, 행정청은 위법 상태의 결과를 없앨 의무를 집니다.","주민등록번호가 본인 의사와 무관하게 유출된 사람의 변경신청, 도시계획구역 내 토지소유자의 도시계획 입안·변경신청, 공사중지명령 원인 소멸 후 철회신청":"유출된 주민등록번호의 변경신청, 도시계획 입안신청, 공사중지명령 원인 소멸 후의 철회신청에는 조리상 신청권이 인정됩니다.","주체·절차·형식뿐 아니라 내용상 위법도 포함된다":"재결 고유의 위법에는 주체·절차·형식의 위법뿐 아니라 내용상 위법도 들어갑니다.","준공처분을 하지 말라는 소송 등":"행정청이 미래에 어떤 처분을 하지 못하도록 미리 막는 소송은 허용되지 않으며, 준공처분을 하지 말라는 청구가 그 예입니다.","중대한 손해는 행정심판법상 집행정지 요건이다":"중대한 손해는 행정심판법상 집행정지 요건으로, 행정소송법의 요건과 표현이 다릅니다.","중앙행정기관과 그 부속기관, 합의제행정기관 또는 그 장, 국가 사무를 위임·위탁받은 공공단체 또는 그 장이 피고이면 대법원소재지를 관할하는 행정법원에도 낼 수 있다":"중앙행정기관과 부속기관, 합의제행정기관, 위임받은 공공단체가 피고이면 대법원 소재지 관할 법원에도 소를 낼 수 있습니다.","증명은 고도의 개연성으로 족하다":"처분의 위법 증명은 고도의 개연성이 있으면 충분하며 확신까지 필요하지는 않습니다.","증액·감액 항목을 함께 경정한 결과 전체 소득처분금액이 줄었다면 소득금액변동통지 취소를 구할 이익이 없다":"증액과 감액을 함께 고쳐 결과적으로 소득처분 금액이 줄었다면 납세자에게 남은 불이익이 없으므로 통지 취소를 구할 이익이 없습니다.","지금은 국가를 상대로 한 당사자소송에서도 가집행선고를 할 수 있다":"위헌결정과 조항 삭제 뒤에는 국가가 피고인 당사자소송에서도 가집행선고를 붙일 수 있다는 결론입니다.","지방의회 의원 제명 후 임기만료, 입학시기가 지난 불합격처분, 감봉 후 자진퇴직한 공무원의 감봉처분":"제명 후 임기만료, 입학시기가 지난 불합격처분, 퇴직 후 감봉처분은 효과가 끝난 듯하나 불이익이 남아 있어 소의 이익이 인정된 예입니다.","지방의회 의원 징계는 처분으로서 항고소송으로 다툰다":"지방의회가 의원에게 내리는 징계는 법적 효과가 있는 처분이라서 항고소송의 대상이 됩니다.","지방의회 의장선임의결, 이행강제금 최초 독촉":"지방의회 의장선임의결과 이행강제금의 최초 독촉은 법적 효과가 직접 생겨 처분으로 인정됩니다.","지방의회 의장선임의결은 지방의회가 피고이다":"지방의회가 한 의장선임의결은 의회 자체가 처분을 한 것이므로 지방의회가 피고입니다.","지방의회 재의결에 대해 단체장이나 교육감이 대법원에 내는 소송이 대표 예이다":"지방의회가 재의결하면 단체장이나 교육감이 이를 다투려고 대법원에 제소하는 소송이 기관소송의 대표적 예입니다.","지방자치단체는 다른 지방자치단체장의 건축협의 취소를 다툴 수 있다":"지방자치단체도 다른 지방자치단체장이 건축협의를 취소한 것에 대해서는 소송으로 다툴 수 있는 지위가 인정됩니다.","직권조사사항이고 사실심 변론종결시는 물론 상고심에서도 존속해야 한다":"원고적격은 법원이 직권으로 조사하며 사실심 변론종결 때는 물론 상고심에서도 계속 유지되어야 합니다.","직권조사사항이 아닌 위법사유는 취소를 구하는 원고가 구체적 사실을 먼저 주장해야 한다":"직권조사 대상이 아닌 위법사유는 원고가 구체적 사실을 들어 먼저 주장해야 법원이 판단할 수 있습니다.","직권취소를 할 수 있다는 사정만으로 이해관계인에게 취소 신청권이 생기지 않는다":"행정청에 직권취소 권한이 있어도 이는 행정청의 재량일 뿐이어서 이해관계인에게 취소를 신청할 권리가 따로 생기지는 않습니다.","집행정지, 처분변경으로 인한 소의 변경, 사정판결은 준용되지 않는다":"부작위위법확인소송에는 집행정지, 처분변경에 의한 소 변경, 사정판결 규정이 적용되지 않는다는 점이 취소소송과 다릅니다.","집행정지결정과 기각결정 모두 즉시항고할 수 있지만 집행정지결정에 대한 즉시항고에는 집행을 정지하는 효력이 없다(제23조 제5항)":"집행정지결정과 기각결정에는 모두 즉시항고가 가능하지만, 정지결정에 대한 즉시항고는 집행을 멈추게 하는 효력이 없습니다.","집행정지결정은 제3자에게도 효력이 있고 당사자인 행정청과 관계행정청을 기속한다(제29조 제2항, 제23조 제6항)":"집행정지결정은 제3자에게도 효력이 있고 당사자인 행정청과 관계행정청을 구속합니다.","집행정지결정이 확정된 뒤에도 공공복리에 중대한 영향을 미치거나 정지사유가 없어지면 당사자의 신청 또는 직권으로 결정을 취소할 수 있다(제24조)":"집행정지결정이 확정된 뒤라도 공공복리에 중대한 영향이 생기거나 정지사유가 사라지면 법원이 신청이나 직권으로 이를 취소합니다.","집행정지는 당사자의 신청 또는 법원의 직권으로 결정한다":"집행정지는 당사자의 신청뿐 아니라 법원의 직권으로도 결정할 수 있습니다.","참가 이익은 법률상 이익이어야 하고 참가인은 공동소송적 보조참가인의 지위를 가진다":"참가하려면 법률상 이익이 필요하고, 참가인은 공동소송적 보조참가인의 지위에 놓입니다.","처분등에는 행정심판에 대한 재결이 포함된다(제2조)":"행정심판에 대한 재결도 처분등에 들어가므로 재결을 상대로도 항고소송을 낼 수 있습니다.","처분등을 원인으로 하는 법률관계나 그 밖의 공법상 법률관계에 관한 소송으로 법률관계의 한쪽 당사자를 피고로 한다(제3조 제2호)":"당사자소송은 처분등을 원인으로 하는 법률관계나 공법상 법률관계의 한쪽 당사자를 피고로 하는 소송입니다.","처분등의 효력 유무 등의 확인을 구할 법률상 이익이 있는 자가 제기하고 처분 상대방이 아닌 제3자도 법률상 이익이 있으면 된다(제35조)":"무효등 확인소송은 확인을 구할 법률상 이익이 있는 자가 제기하며, 처분 상대방이 아닌 제3자도 법률상 이익이 있으면 됩니다.","처분등의 효력 유무 또는 존재 여부를 확인하는 소송으로 무효확인, 유효확인, 실효확인, 존재확인, 부존재확인이 포함되고 재결의 무효확인도 된다":"무효등 확인소송은 처분의 효력 유무나 존재 여부를 확인하는 소송으로 무효·유효·실효·존재·부존재 확인과 재결의 무효확인이 있습니다.","처분 상대방이 위명을 사용했어도 처분의 효과가 그에게 미치므로 원고적격이 있다":"위명으로 처분을 받았더라도 처분의 효과가 실제 그 사람에게 미치므로 원고적격이 인정됩니다.","처분서가 주소지에 송달되면 반증이 없는 한 알았다고 추정할 뿐 간주하지는 않는다":"처분서가 주소지에 송달되면 반증이 없는 한 알았다고 추정하지만, 알았다고 간주하는 것은 아닙니다.","처분에 이의가 있는 당사자는 처분을 받은 날부터 30일 이내에 해당 행정청에 이의신청(행정기본법 제36조)":"행정기본법상 이의신청은 처분을 받은 날부터 30일 안에 그 처분을 한 행정청에 하는 제도입니다.","처분을 취소하는 확정판결로 처분은 처분시에 소급해 소멸한다":"처분을 취소하는 확정판결은 형성력이 있어 처분이 처분 시점으로 소급해 소멸합니다.","처분을 취소하는 확정판결은 당사자인 행정청과 그 밖의 관계행정청을 기속하고(제30조 제1항) 원고에게는 미치지 않는다":"취소 확정판결은 당사자인 행정청과 관계행정청을 기속하고 원고에게는 기속력이 미치지 않습니다.","처분의 근거 법규와 관련 법규가 보호하는 개별적·직접적·구체적 이익":"법률상 이익은 근거 법규와 관련 법규가 보호하는 이익 중 개별적·직접적·구체적인 것만을 가리킵니다.","처분의 신청을 한 자로서 부작위 위법 확인을 구할 법률상 이익이 있는 자만 제기한다(제36조)":"부작위위법확인소송은 처분을 신청한 사람 중 부작위 위법 확인을 구할 법률상 이익이 있는 사람만 제기할 수 있습니다.","처분의 위법성은 소송요건이 아니라 본안 판단 사항이다":"처분이 위법한지는 본안에서 판단할 내용이므로 소송요건의 구성 요소가 아닙니다.","처분의 존재 여부도 심리 대상이다":"무효등 확인소송에서는 처분이 존재하는지 여부도 심리 대상이 됩니다.","처분의 효과가 기간 경과·집행 등으로 소멸한 뒤에도 취소로 회복되는 법률상 이익이 있으면 소를 낼 수 있다(제12조 제2문)":"처분 효과가 기간 경과나 집행으로 사라진 뒤에도 취소로 회복할 법률상 이익이 있으면 소를 낼 수 있다는 규정이 제12조 제2문입니다.","처분의 효력 유무가 민사소송의 선결문제이면 수소법원에 행정청의 소송참가, 행정심판기록 제출명령, 직권심리, 소송비용 재판의 효력 규정이 준용되고 재판관할·사정판결은 준용되지 않는다(제11조)":"민사소송에서 처분 효력이 선결문제가 되면 일부 규정만 준용되어 행정청 소송참가 등은 가능하나 재판관할과 사정판결은 적용되지 않습니다.","처분의 효력정지는 집행이나 절차 속행 정지로 목적을 이룰 수 있으면 허용되지 않고 처분 효력의 일부만 정지할 수도 있다":"집행이나 절차 속행을 멈추는 것만으로 충분하면 효력정지는 허용되지 않으며, 효력은 일부만 정지시키는 것도 가능합니다.","처분이 가분이고 취소할 부분을 특정할 수 있을 때만 하므로 세대별로 나뉘는 분양전환승인, 분리되는 공개 가능 정보, 상이별 국가유공자 비해당결정은 그 부분만 취소한다":"일부취소는 처분이 나뉠 수 있고 취소할 부분을 특정할 수 있을 때만 가능하며, 세대별 분양전환승인이나 분리되는 공개 정보가 그 예입니다.","처분이 적법하다고 확정되어 정지가 끝나면 처분의 효력이 되살아나 정지기간 중 교부된 보조금의 반환을 명할 수 있다":"처분이 적법하다고 확정되면 정지되었던 효력이 되살아나 정지된 동안 지급된 보조금까지 되돌려 달라고 명할 수 있습니다.","처분청과 통지한 자가 다르면 처분청이 피고이다":"처분청과 통지를 한 사람이 다르면 처분 권한이 있는 처분청이 피고입니다.","처분청의 권한 유무, 행정절차법상 처분절차 준수, 재량남용 여부":"처분청의 권한 유무, 행정절차법상 절차 준수, 재량남용 여부는 본안에서 판단하는 사항입니다.","청구가 이유 있어도 처분을 취소하는 것이 현저히 공공복리에 적합하지 않으면 기각할 수 있고 주문에 처분이 위법함을 명시한다(제28조)":"사정판결은 청구가 이유 있어도 취소가 현저히 공공복리에 맞지 않을 때 기각하되 주문에 처분이 위법함을 명시하는 판결입니다.","청구기간을 넘겨 각하된 재결 뒤에는 재결서 송달일이 아니라 원처분을 안 날이 기준이어서 그 뒤에 낸 소는 기간을 지킨 것이 아니다":"심판청구 기간을 넘겨 각하된 경우에는 재결서를 받은 날이 아니라 원처분을 안 날부터 세므로 그 뒤 낸 소는 기간을 넘긴 소입니다.","청구취지를 교환적으로 변경하거나 추가한 경우는 원칙적으로 변경·추가 신청이 있은 때가 기준이다":"청구취지를 교환적으로 바꾸거나 추가하면 원칙적으로 변경·추가 신청이 있은 때가 제소기간 기준입니다.","취소결정과 그 불복에는 집행정지의 소명·즉시항고 규정이 준용된다":"집행정지 취소결정과 그에 대한 불복에는 집행정지의 소명·즉시항고 규정이 그대로 준용됩니다.","취소사유에 그치는 하자 있는 처분의 효력은 공정력 때문에 당사자소송에서 부정할 수 없다":"취소사유만 있는 하자 있는 처분은 공정력 때문에 효력이 유지되므로 당사자소송에서 그 효력을 부정할 수 없습니다.","취소소송, 무효등 확인소송, 부작위위법확인소송으로 나뉜다(제4조)":"항고소송은 취소소송, 무효등 확인소송, 부작위위법확인소송의 세 가지로 나뉘며 법 제4조에 규정되어 있습니다.","취소소송과 무효등 확인소송(처분부존재확인 포함)에 인정된다":"집행정지는 취소소송과 처분부존재확인을 포함한 무효등 확인소송에서 인정됩니다.","취소소송·당사자소송으로 소를 변경할 수 있다(제37조)":"무효등 확인소송은 취소소송이나 당사자소송으로 소를 변경하는 것이 허용됩니다.","취소소송에서 일부취소는 되지만 처분을 다른 내용으로 바꾸라는 적극적 변경은 구할 수 없다":"취소소송에서 법원은 처분의 일부를 취소할 수는 있으나 처분을 다른 내용으로 바꾸라는 적극적 변경은 판결로 할 수 없습니다.","취소소송에서 처분의 적법성은 원칙적으로 피고 행정청이 증명한다":"취소소송에서는 처분이 적법하다는 것을 원칙적으로 피고인 행정청이 증명해야 합니다.","취소소송은 처분등을 대상으로 하고 재결취소소송은 재결 자체에 고유한 위법이 있을 때만 허용된다(제19조)":"원처분주의는 취소소송이 원래의 처분등을 대상으로 하고, 재결을 다투는 소송은 재결에 고유한 위법이 있을 때만 허용된다는 원칙입니다.","취소소송은 처분등의 취소를 구할 법률상 이익이 있는 자가 제기한다(제12조)":"취소소송은 처분등을 취소해 달라고 구할 법률상 이익이 있는 사람만 원고가 되어 제기할 수 있습니다.","취소소송은 처분등이 있음을 안 날부터 90일 이내, 처분등이 있은 날부터 1년 이내에 제기해야 하고 둘 중 하나라도 지나면 제기하지 못한다(제20조)":"취소소송은 처분이 있음을 안 날부터 90일, 처분이 있은 날부터 1년 중 어느 하나라도 지나면 제기할 수 없습니다.","취소소송은 청구의 기초에 변경이 없는 한 사실심 변론종결시까지 원고의 신청으로 당사자소송이나 다른 항고소송으로 변경할 수 있고 허가결정에는 즉시항고할 수 있다(제21조)":"청구의 기초가 바뀌지 않으면 사실심 변론종결 때까지 소의 종류를 당사자소송이나 다른 항고소송으로 변경할 수 있습니다.","취소소송을 제기해도 처분등의 효력이나 집행, 절차의 속행은 멈추지 않는다(집행부정지 원칙, 제23조 제1항)":"취소소송을 제기해도 처분의 효력이나 집행, 절차 속행이 멈추지 않는 것을 집행부정지 원칙이라 합니다.","취소소송의 제1심 관할법원은 피고의 소재지를 관할하는 행정법원이다(제9조 제1항)":"취소소송은 피고 소재지를 관할하는 행정법원이 제1심을 맡습니다.","취소판결로 권리를 침해받은 제3자가 자기에게 책임 없는 사유로 소송에 참가하지 못해 공격방어방법을 내지 못했으면 확정판결을 안 날부터 30일, 확정된 날부터 1년 이내에 재심을 청구할 수 있고 이는 불변기간이다(제31조)":"취소판결로 권리를 침해받은 제3자는 책임 없이 참가하지 못해 방어하지 못했다면 안 날부터 30일, 확정일부터 1년 안에 재심을 청구합니다.","취소판결만으로 처분을 기초로 새로 형성된 제3자의 권리가 당연히 원상회복되지는 않는다":"취소판결이 확정돼도 그 처분을 기초로 새로 형성된 제3자의 권리가 당연히 원상회복되는 것은 아닙니다.","취소판결은 제3자에게도 효력이 있고(제29조) 집행정지결정과 그 취소결정, 무효확인판결, 부작위위법확인판결에도 준용되지만 당사자소송과 기각판결에는 제3자효가 없다":"제3자효는 취소판결과 그에 준하는 판결에 있으나, 소송 당사자들만 관련된 당사자소송과 기각판결에는 효력이 제3자에게 미치지 않습니다.","토지수용 등 부동산이나 특정 장소에 관계되는 처분은 그 소재지 행정법원에도 낼 수 있고 토지관할은 전속관할이 아니다":"부동산·특정 장소에 관한 처분은 현장 소재지 법원에서도 다툴 수 있고, 이 토지관할은 반드시 한 곳으로 정해진 전속관할이 아닙니다.","토지수용재결에 대한 보상금증감청구소송은 토지소유자가 사업시행자를 피고로 제기한다":"토지수용재결의 보상금증감청구소송은 토지소유자가 사업시행자를 피고로 하는 형식적 당사자소송입니다.","특허심판원 심결취소소송은 특허법원 전속관할이다":"특허심판원 심결을 취소해 달라는 소송은 특허법원이 전속으로 맡습니다.","판결이 확정되면 행정청은 이전 신청에 대해 처분할 의무를 지지만 신청대로 할 필요는 없어 거부처분을 해도 의무를 이행한 것이다":"확정판결 후 행정청은 이전 신청을 처분하기만 하면 되고 신청대로 할 의무는 없어서, 거부처분을 해도 의무를 다한 것입니다.","판례는 본안청구가 이유 없음이 명백하지 않을 것도 요건으로 본다":"판례가 덧붙이는 소극적 요건으로, 본안 청구가 이유 없음이 분명하면 집행정지가 허용되지 않습니다.","폐기물처리 사업계획 부적정통보, 지방의료원 폐업결정":"폐기물처리 사업계획의 부적정통보와 지방의료원의 폐업결정도 법적 지위를 바꾸는 처분으로 인정된 예입니다.","피고경정, 공동소송, 제3자·행정청 소송참가, 처분변경으로 인한 소의 변경, 기록 제출명령, 직권심리, 기속력(제30조 제1항), 소송비용 규정이 준용되고(제44조) 관할은 관계행정청 소재지를 피고 소재지로 본다(제40조)":"당사자소송에는 피고경정, 참가, 소 변경, 기록 제출명령, 직권심리, 기속력 등이 준용되고 관할은 관계행정청 소재지를 피고 소재지로 취급합니다.","피고는 처분을 한 행정청이고 처분 후 권한이 승계되면 승계한 행정청, 행정청이 없어지면 사무가 귀속되는 국가 또는 공공단체가 피고이다":"피고는 처분을 한 행정청이 원칙이고, 권한이 이전되면 이를 이어받은 행정청, 행정청이 폐지되면 그 사무가 귀속한 국가나 공공단체입니다.","피고적격, 제소기간, 제3자 재심청구 규정은 준용되지 않는다":"당사자소송에는 피고적격, 제소기간, 제3자 재심청구에 관한 항고소송 규정이 적용되지 않습니다.","항고소송에서 처분의 위법 여부는 처분 당시의 법령과 사실상태를 기준으로 하고 처분 후 법령 개폐나 사실 변동에 영향을 받지 않는다":"항고소송에서 위법 여부는 처분 당시의 법령과 사실상태를 기준으로 하며, 그 뒤 법령이 바뀌어도 영향을 받지 않습니다.","해사행정사건 취소소송과 관련청구소송의 이송·병합은 해사국제상사법원에만 할 수 있다(제10조 제3항)":"해사행정사건의 취소소송과 관련청구소송을 이송·병합하는 일은 해사국제상사법원에서만 할 수 있습니다.","해임·파면 후 임기만료나 당연퇴직이 생겨도 그 사이 보수를 청구할 수 있으면 소의 이익이 있다":"해임이나 파면 뒤 임기가 끝나도 그 사이 보수를 청구할 수 있다면 처분 취소로 얻는 이익이 남아 소의 이익이 있습니다.","행정소송규칙 제10조는 종기를 본안판결 선고일부터 30일 이내의 범위에서 정하도록 한다":"행정소송규칙 제10조에 따라 집행정지의 종기는 본안판결 선고일부터 30일 이내의 범위에서 정합니다.","행정소송규칙 제19조는 이런 유형과 공법상 계약에 따른 이행청구를 열거한다":"행정소송규칙 제19조는 당사자소송의 유형과 공법상 계약에 따른 이행청구를 열거해 두고 있습니다.","행정소송법에 기판력 규정은 없고 민사소송법이 준용된다":"행정소송법에 기판력 규정이 없어 민사소송법의 기판력 규정이 준용됩니다.","행정소송법에는 규정이 없고 판례와 행정소송규칙 제9조가 사실심 변론종결시까지 당초 처분사유와 기본적 사실관계가 동일한 범위에서 허용한다":"처분사유의 추가·변경은 판례와 행정소송규칙 제9조에 따라 변론종결 때까지 기본적 사실관계가 같은 범위에서 허용됩니다.","행정소송법에는 제소기간 불고지·오고지 규정이 없어 행정청이 긴 기간을 알려도 법정 기간이 지나면 부적법하다":"행정소송법에는 제소기간을 알리지 않거나 잘못 알린 경우의 규정이 없어, 행정청이 긴 기간을 안내해도 법정 기간이 지나면 부적법합니다.","행정소송법에 특별한 규정이 없는 사항은 법원조직법과 민사소송법 및 민사집행법을 준용한다(제8조 제2항)":"행정소송법에 규정이 없는 사항은 법원조직법, 민사소송법, 민사집행법의 규정을 가져다 씁니다.","행정소송은 변론주의를 기본 구조로 하고 직권심리가 보충적으로 더해진다":"행정소송의 심리는 당사자가 주도하는 변론주의가 바탕이고 법원이 직권으로 보충하는 이중 구조입니다.","행정심판기록 제출명령은 당사자의 신청이 있을 때 재결청에 결정으로 하며(제25조) 당사자소송에도 준용된다":"행정심판기록 제출명령은 당사자가 신청하면 재결청에 결정으로 하며 당사자소송에도 준용됩니다.","행정심판법은 준용되지 않는다":"행정심판법은 행정소송에 준용되는 법률에 들어 있지 않습니다.","행정심판은 원칙적으로 거치지 않고도 취소소송을 낼 수 있다(제18조)":"취소소송은 행정심판을 거치지 않고 바로 낼 수 있는 것이 원칙입니다.","행정심판을 거치지 않으면 부작위가 계속되는 한 제소기간 제한이 없고 거쳤다면 재결서 정본을 송달받은 날부터 90일 안에 제기한다":"행정심판을 안 거치면 부작위가 계속되는 동안 언제든 소를 낼 수 있고, 심판을 거쳤다면 재결서 정본 송달일부터 90일 안에 내야 합니다.","행정심판청구를 한 경우에는 재결서 정본을 송달받은 날부터 90일, 재결이 있은 날부터 1년이 제소기간이다":"행정심판을 거친 경우 제소기간은 재결서 정본을 송달받은 날부터 90일이고 재결이 있은 날부터 1년입니다.","행정처분의 금지를 구하는 민사집행법상 가처분은 허용되지 않는다":"민사집행법상 가처분으로 행정처분 자체를 금지해 달라고 구하는 것은 허용되지 않습니다.","행정청은 14일 이내에 결과를 통지":"이의신청을 받은 행정청은 14일 안에 결과를 신청인에게 알려야 합니다.","행정청의 처분등이나 부작위에 대하여 제기":"항고소송은 행정청이 한 처분이나 해야 할 처분을 하지 않은 부작위를 상대로 제기하는 소송입니다.","행정청이 구체적 사실에 관하여 하는 법집행으로서 공권력의 행사 또는 그 거부와 이에 준하는 행정작용(제2조)":"처분이란 행정청이 구체적 사실에 관해 하는 법집행으로서 공권력의 행사나 그 거부 및 이에 준하는 행정작용입니다.","행정청이 당사자의 신청에 대하여 상당한 기간 내에 일정한 처분을 할 법률상 의무가 있는데도 하지 않는 것이다(제2조)":"부작위란 행정청이 신청에 대해 상당한 기간 안에 일정한 처분을 할 법률상 의무가 있는데도 하지 않는 상태입니다.","행정청이 재처분을 하지 않거나 기속력에 반하는 재처분을 하면 당사자의 신청으로 제1심수소법원이 결정하여 지연배상이나 즉시 손해배상을 명한다(제34조)":"행정청이 재처분을 안 하거나 기속력에 반하는 재처분을 하면 제1심 수소법원이 신청에 따라 지연배상 등을 명하는 것이 간접강제입니다.","허가기준 미달 불허가처분, 과세소득과 그 귀속 사업연도, 정보공개 비공개사유도 피고가 증명한다":"불허가처분의 허가기준 미달, 과세소득과 귀속연도, 정보공개 비공개사유는 처분의 적법성을 뒷받침하는 사실이라 피고가 입증합니다.","허가신청 후 기준이 바뀌면 바뀐 기준에 따라 처분하는 것이 원칙이고 행정청이 정당한 이유 없이 처리를 늦춘 경우만 예외이다":"신청 뒤 기준이 바뀌면 바뀐 기준으로 처분하는 것이 원칙이며, 행정청이 정당한 이유 없이 지연한 때만 예외입니다.","확인소송 형태의 당사자소송에는 민사소송과 같은 확인의 이익이 필요하다":"확인소송 형태의 당사자소송은 민사소송과 같은 확인의 이익이 있어야 제기할 수 있습니다.","확인판결뿐 아니라 이행판결도 할 수 있다":"당사자소송에서는 확인판결뿐 아니라 이행판결도 선고할 수 있습니다.","환경영향평가 대상지역 안의 주민, 원자로시설부지 인근 주민, 오염 우려 취수장에서 물을 받는 주민은 환경상 이익 침해가 사실상 추정된다":"환경영향평가 대상지역 안 주민, 원자로 인근 주민, 오염 우려 취수장 이용 주민은 환경상 이익 침해가 사실상 추정되어 원고적격이 있습니다.","회복하기 어려운 손해에는 금전으로 보상할 수 없는 손해와 무형의 손해도 들어간다":"회복하기 어려운 손해에는 금전보상이 불가능한 손해와 무형의 손해도 포함됩니다.","회복하기 어려운 손해와 신청 이유는 신청인이 소명해야 한다":"신청인이 소명할 사항은 회복하기 어려운 손해와 신청 이유이고, 공공복리 침해 우려는 행정청 몫입니다.","효력은 장래를 향해서만 생기고 기간이 끝나거나 본안이 확정되어도 소급해 소멸하지 않는다":"집행정지의 효력은 장래를 향해서만 생기고 기간 만료나 본안 확정이 있어도 소급해 소멸하지 않습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
